import{_ as o,o as l,c as a,j as t}from"./chunks/framework.BdHuibk5.js";const u=JSON.parse('{"title":"日志（2008.12.08）","description":"中午在学校第一次尝试献血，圆了一个惦记了两年的小愿望。虽然紧张又心疼，但拿到献血证的时候，还是挺自豪的。","frontmatter":{"title":"日志（2008.12.08）","date":"2008-12-08","category":"diary","tags":["生活","校园"],"slug":"log-2008-12-08","layout":"blog-post","description":"中午在学校第一次尝试献血，圆了一个惦记了两年的小愿望。虽然紧张又心疼，但拿到献血证的时候，还是挺自豪的。"},"headers":[],"relativePath":"blog/log-2008-12-08.md","filePath":"blog/posts/diary/log-2008-12-08.md","lastUpdated":1789447662000}'),s={name:"blog/log-2008-12-08.md"};function r(n,e,p,d,i,c){return l(),a("div",null,[...e[0]||(e[0]=[t("p",null,"今天中午学校里，我尝试了第一次献血，也圆了我多年的梦，呵呵，其实也就两年啦！不过当时也挺紧张的，先排队验血，我今天才知道自己竟然是 B 型血，我一直以为是 O 型的，不这样也好，等到哪天急用血时找不到了。",-1),t("p",null,"终于排到了，上了车心跳加快了，还是紧张（第一次嘛，免不了得）。等到轮到我时，看着这么大的针头……吓人！！当它插进我的血管时，又痛得不行，可能是心理在作怪吧。过了没几分钟我的 400 毫升血就这样没了，以前流了这么多次血也没有这次多吧。呵呵，有点心疼了现在。要知道 400 毫升血要补多长时间才能补回来呀！不过还好，等到结束后有一瓶牛奶和手套送的，嘿嘿，这也是我献血的动力呀。不过血在不知不觉中流走，其实是没多大感觉的。结束后也没什么反应，要是允许的话我可以再献血 100 毫升应该没问题吧，谁叫我血多呢。",-1),t("p",null,"恩，还拿了个献血证，红红的，挺自豪的呀！",-1),t("p",null,"（PS：邱国兴、马文超一起，忘记马文超有没有献了，好像只献了 300ml。中午饭后献的血，献完之后是去上了素描课。之后上体育课时邱国兴晕了，血糖过低。）",-1)])])}const m=o(s,[["render",r]]);export{u as __pageData,m as default};
